287: function updateActivityAnimation(dt){
288:   if(!activityAnimation)return;const a=activityAnimation;a.elapsed+=dt;const phase=Math.min(1,a.elapsed/a.duration),reach=THREE.MathUtils.smoothstep(phase,.06,.36)*(1-THREE.MathUtils.smoothstep(phase,.68,.98));
289:   hands.forEach(({arm,rest,side})=>{
290:     const active=side===1||['sleep','computer','study','work','shower'].includes(a.mode);const amount=reach*(active?1:.2);
291:     let targetY=rest.y-.08,targetZ=rest.z-.12,rx=-.25,rz=side*-.12;
292:     if(a.mode==='eat'){targetY=rest.y+.18;targetZ=rest.z+.04;rx=-1.05}
293:     if(a.mode==='exercise'){const lift=.48+Math.sin(a.elapsed*7)*.09;targetY=rest.y+lift;targetZ=rest.z+.08;rx=-1.25+Math.sin(a.elapsed*7)*.12}
294:     if(a.mode==='shower'){targetY=rest.y+.42;targetZ=rest.z+.02;rx=-1.2}
295:     if(a.mode==='clean'){targetY=rest.y-.05+Math.sin(a.elapsed*9)*.08;targetZ=rest.z-.2;rx=-.65+Math.sin(a.elapsed*9)*.22}
296:     if(a.mode==='sleep'){targetY=rest.y-.2;targetZ=rest.z+.18;rx=.35}
297:     if(a.mode==='computer'||a.mode==='study'||a.mode==='work'){targetY=rest.y-.03;targetZ=rest.z-.32;rx=-.12}
298:     if(a.mode==='shopping'||a.mode==='travel'){targetY=rest.y-.02;targetZ=rest.z-.18;rx=-.45}
299:     if(a.mode==='entertainment'){targetY=rest.y+.03;targetZ=rest.z-.15;rx=-.55}
300:     arm.position.set(rest.x,rest.y,rest.z).lerp(new THREE.Vector3(rest.x+side*.06,targetY,targetZ),amount);
301:     arm.rotation.x=THREE.MathUtils.lerp(0,rx,amount);arm.rotation.z=THREE.MathUtils.lerp(side*-.08,rz,amount);
302:   });
303:   if(a.mode==='sleep')camera.position.y=THREE.MathUtils.lerp(1.67,1.42,reach);else camera.position.y=THREE.MathUtils.lerp(camera.position.y,1.67,Math.min(1,dt*5));
304:   if(phase>=1){camera.position.y=1.67;a.arm.remove(a.prop);a.prop.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material)o.material.dispose()});activityAnimation=null}
